from lib import *
S = SS('l63')
steps = [
    step("给仓库装上一组“只记录自己被调用”的 hook(把名字和参数追加到日志)。git commit 触发的顺序:pre-commit(无参数)→ prepare-commit-msg(参数:.git/COMMIT_EDITMSG 消息文件,来源 message,表示说明是用 -m 给的)→ commit-msg(参数:消息文件)→ post-commit(无参数)。前三个可以在提交完成前干预,post-commit 在提交已经完成之后。", t=tl(S(1)), mark=lidx(S(1), 'pre-commit', 'prepare-commit-msg', 'commit-msg', 'post-commit'), done=lidx(S(1), '.git/COMMIT_EDITMSG message'), kv=KV([['pre-commit', '提交前检查,无参数'], ['prepare-commit-msg', '预填说明'], ['commit-msg', '校验或改写说明'], ['post-commit', '完成后通知']], ['pre-commit'])),
    step("退出码的影响:pre-commit 退出 1 → git commit 退出码 1,提交数不变(1),只触发了 pre-commit;commit-msg 退出 1 → 同样中止,触发了 pre-commit → prepare-commit-msg → commit-msg;post-commit 退出 1 → git commit 退出码仍是 0,提交已经创建(提交数 2),因为它在提交之后,退出码被忽略。--no-verify 跳过 pre-commit 和 commit-msg(两个都退出 1 也能提交成功,提交数 2),但 prepare-commit-msg 和 post-commit 仍然会运行。", t=tl(S(2)), mark=lidx(S(2), 'pre-commit 退出 1', 'commit-msg 退出 1', 'post-commit 退出 1', '--no-verify'), done=lidx(S(2), '退出码 1,提交数 1', '退出码 0,提交数 2'), kv=KV([['pre-commit / commit-msg 非 0', '中止提交'], ['post-commit 非 0', '被忽略'], ['--no-verify', '跳过 pre-commit 和 commit-msg']], ['--no-verify'])),
    step("commit-msg 可以改写提交说明:这个 hook 往消息文件末尾追加一行 [审核通过],git log 看到的完整说明就是“原始说明”加一个空行再加“[审核通过]”。commit-msg 收到的是消息文件的路径,改写这个文件就改写了最终的提交说明。", t=tl(S(3)), mark=lidx(S(3), '[审核通过]'), done=lidx(S(3), '原始说明'), kv=KV([['commit-msg 的参数', '消息文件路径'], ['改写', '修改文件即可'], ['用途', '加 Change-Id、检查格式']], ['commit-msg 的参数'])),
    step("其它客户端 hook:git checkout side 触发 post-checkout,三个参数:旧 HEAD、新 HEAD、1(切换分支;检出文件时是 0)。git merge(非快进)依次触发 pre-merge-commit、prepare-commit-msg(.git/MERGE_MSG merge)、commit-msg、post-merge(参数 0 表示不是 squash)。git rebase main 触发 pre-rebase(参数是上游 main)、post-checkout(切到新基础)、对每个重放的提交触发 prepare-commit-msg 和 post-commit,最后 post-rewrite(参数 rebase,stdin 每行“旧 sha 新 sha”)。", t=tl(S(4)), mark=lidx(S(4), 'pre-merge-commit', 'post-merge 0', 'pre-rebase main', 'post-rewrite rebase'), done=lidx(S(4), 'post-checkout', 'prepare-commit-msg .git/MERGE_MSG merge', 'stdin: <sha40> <sha40>'), kv=KV([['post-checkout', '旧 HEAD、新 HEAD、分支标志'], ['merge', 'pre-merge-commit … post-merge'], ['rebase', 'pre-rebase … post-rewrite(stdin 旧新对应)']], ['post-rewrite'])),
    step("git push 触发 pre-push:参数是远程名(origin)和远程 URL,stdin 每行 “本地ref 本地sha 远程ref 远程sha”(这里是 refs/heads/main <sha> refs/heads/main <sha>,新建的 ref 远程 sha 是全 0)。pre-push 退出 1:git push 退出码 1,远程 main 仍只有 1 个提交——非 0 阻止推送。", t=tl(S(5)), mark=lidx(S(5), 'stdin: refs/heads/main', 'pre-push 退出 1'), done=lidx(S(5), 'pre-push origin'), kv=KV([['参数', '远程名 与 URL'], ['stdin', '本地ref sha 远程ref sha'], ['非 0', '阻止推送']], ['stdin'])),
    step("服务端 hook(裸仓库):一次推送 main 和 topic 两个 ref,顺序是 pre-receive(一次,stdin 每行“旧 新 ref”)→ update(每个 ref 各一次,参数 ref 旧 新)→ post-receive(一次,stdin 同 pre-receive)→ post-update(一次,参数是更新过的 ref 列表)。update 对 topic 退出 1:只拒绝 topic(! [remote rejected] topic -> topic (hook declined)),main 照常更新(远程 main 变成 2 个提交);pre-receive 退出 1:整个推送被拒绝,显示 main -> main (pre-receive hook declined)。", t=tl(S(6)), mark=lidx(S(6), 'update refs/heads/topic', 'hook declined', 'pre-receive hook declined'), done=lidx(S(6), 'pre-receive', 'post-receive', 'post-update refs/heads/main refs/heads/topic'), kv=KV([['pre-receive', '一次,可拒绝整个推送'], ['update', '每个 ref 一次,可拒绝单个 ref'], ['post-receive / post-update', '成功之后,通知用']], ['update'])),
    step("常见的坑:去掉 pre-commit 的可执行位,git 只给出 hint: The '.git/hooks/pre-commit' hook was ignored because it's not set as executable.,提交照常完成——hook 没有运行。clone 出来的仓库 .git/hooks 里没有这个 hook(clone 不复制 hook,里面只有 14 个 *.sample 示例文件);要让团队共用,可以设置 core.hooksPath 指向一个共享目录:设置后提交时运行的是“来自 core.hooksPath 的 pre-commit”。", t=tl(S(7)), mark=lidx(S(7), 'not set as executable', 'clone 不复制 hook', '来自 core.hooksPath'), done=lidx(S(7), '去掉可执行位', 'core.hooksPath'), kv=KV([['没有可执行位', 'hook 被忽略,只给 hint'], ['clone', '不复制 .git/hooks'], ['core.hooksPath', '指向共享目录']], ['core.hooksPath'])),
]
A = mkarti('l63', 63, 'Git,hooks,pre-commit,pre-receive,退出码,真实验证,动画演示',
    '装上只记录调用的 hook 实测触发时机与顺序:commit 是 pre-commit → prepare-commit-msg → commit-msg → post-commit;前两个检查类 hook 非 0 中止提交,post-commit 被忽略,--no-verify 只跳过前者;checkout、merge、rebase、push 的 hook 参数;服务端 pre-receive → update(每个 ref)→ post-receive → post-update;没有可执行位的 hook 被忽略,clone 不复制 hook,core.hooksPath 可共享。',
    'git hook 什么时候触发、顺序如何、退出码会怎样影响命令?这篇给仓库装一组只记录自己被调用的 hook,逐个动作观察,覆盖客户端提交、合并、变基、推送,以及服务端的 pre-receive、update、post-receive。',
    [('4 个', 'git commit 依次触发的 hook:pre-commit、prepare-commit-msg、commit-msg、post-commit'), ('--no-verify', '只跳过 pre-commit 和 commit-msg,prepare-commit-msg 与 post-commit 仍会运行'), ('update 每个 ref 一次', '服务端 hook 里 pre-receive 与 post-receive 各一次,update 对每个 ref 都运行')],
    [('提交', '<p>commit 触发 <code>pre-commit</code>(无参数)→ <code>prepare-commit-msg</code>(消息文件 + 来源)→ <code>commit-msg</code>(消息文件)→ <code>post-commit</code>。前三个在提交完成前,后者在提交之后。</p>'),
     ('退出码', '<p>pre-commit 和 commit-msg 非 0 会中止提交,post-commit 的退出码被忽略(提交已经存在)。<code>--no-verify</code> 跳过前两者,但不跳过 prepare-commit-msg 与 post-commit。</p>'),
     ('改写说明', '<p>commit-msg 收到消息文件的路径,改写它就改写了最终的提交说明(例如追加 Change-Id)。</p>'),
     ('其它客户端 hook', '<p>checkout 触发 post-checkout(旧 HEAD、新 HEAD、分支标志);非快进合并触发 pre-merge-commit、prepare-commit-msg、commit-msg、post-merge;rebase 触发 pre-rebase、对每个重放的提交触发 prepare-commit-msg 和 post-commit、最后 post-rewrite(stdin 是“旧 新”对应)。</p>'),
     ('推送', '<p>pre-push 收到远程名与 URL,stdin 每行 <code>本地ref 本地sha 远程ref 远程sha</code>;非 0 阻止推送。</p>'),
     ('服务端', '<p>顺序是 <code>pre-receive</code>(一次,可拒绝整个推送)→ <code>update</code>(每个 ref 一次,可拒绝单个)→ <code>post-receive</code> → <code>post-update</code>。</p>'),
     ('坑', '<p>hook 需要可执行位,否则被忽略(只给 hint);clone 不复制 <code>.git/hooks</code>,要共享用 <code>core.hooksPath</code> 指向仓库里或共享目录。</p>')],
    steps,
    [ENV_I_GIT + '。所有 hook 都是同一个小脚本,把自己的名字、参数(有 stdin 的再加 stdin)追加到日志;服务端是本机的裸仓库;输出里的 hash 与路径做了替换',
     '没有验证:pre-auto-gc、post-index-change、reference-transaction、push-to-checkout、fsmonitor-watchman 等其它 hook;applypatch-msg、pre-applypatch 等 git am 相关 hook;hook 的环境变量(GIT_DIR 等);Windows 上 hook 的行为;pre-commit 里对暂存区而非工作区的检查技巧'],
    'hooks')
